 	// -------------------------------------------------------------

	error_reporting(0);

	$strFileName				= "RssFeed.xml";
	$strDomain					= "http://".$_SERVER["HTTP_HOST"];
            
	$strRSSHeader				= "<?xml version=\"1.0\" ?>\n<rss version=\"2.0\">\n  <channel>\n";
	$strRSSChannel				= "    <title>".$SiteName."</title>\n    <link>".$strDomain."</link>\n    <description>Recent ".$SiteName." Articles</description>\n    <language>en-us</language>\n";
	$strRSSFooter				= "  </channel>\n</rss>";

	$dirList			= opendir("../Content");  				
	
	while (($dirPart	= @readdir($dirList)) == true) 
		{  											
			if($dirPart != "." && $dirPart != ".." && $dirPart != "index.php")
				{										
					$Title			= str_replace(".txt", "", str_replace("_", " ", $dirPart));								
					$strFile		= str_replace(".txt", ".php", $dirPart);																					
					$strTemp		= explode("<+>" ,file_get_contents("../Content/".$dirPart));														
							
					$strContent		= str_replace("’", "'", substr(strip_tags(stripslashes(trim($strTemp[4]))), 0, 256));
				
					if(!stristr($Title, "Index of All Articles in the"))
						{
							$strNode   .=  "    <item>\n      <title>".$Title."</title>\n      <description>".$strContent."</description>\n      <link>".$strDomain."/Articles/".$strFile."</link>\n      <guid>".$strDomain."/Articles/".$strFile."</guid>    </item>\n";
						}	
				}														
		}	
            
	closedir($dirList);

	$strRSSFeed					= $strRSSHeader.$strRSSChannel.$strNode.$strRSSFooter;
		          
	$fp							= fopen("../".$strFileName, "w" );
	fwrite($fp, $strRSSFeed);
	fclose( $fp );

	header('location: Publish.php');        
?>